<span class="line"><span style="color:#ABB2BF;">        total </span><span style="color:#56B6C2;">+=</span><span style="color:#ABB2BF;"> x.</span><span style="color:#61AFEF;">size</span><span style="color:#ABB2BF;">(</span><span style="color:#D19A66;">0</span><span style="color:#ABB2BF;">)</span></span>
